def _prefijo_desde_nombre(nombre):
    # Copia de app.models.prefijo_desde_nombre. Las migraciones NO importan código
    # de la app: si mañana cambia esa función, esta migración debe seguir igual.
    palabras = (nombre or "").split()
    if not palabras:
        return "CLI"
    sin_tildes = unicodedata.normalize("NFKD", palabras[0]).encode("ascii", "ignore").decode()
    return re.sub(r"[^A-Za-z0-9]", "", sin_tildes)[:10] or "CLI"


